762	    /// Lint a single file, returning an empty diagnostics list if the file is ignored.
763	    fn run_file(&self, uri: &Uri, content: Option<&str>) -> Result<Vec<Diagnostic>, String> {
764	        let Some(uri_path) = uri.to_file_path() else {
765	            return Ok(Vec::new());
766	        };
767	        if self.is_ignored(&uri_path) {
768	            return Ok(Vec::new());
769	        }
770	
771	        let reports = self.lint_path(&uri_path, uri, content)?;
772	
773	        let mut diagnostics = Vec::with_capacity(reports.len());
774	        // mostly all diagnostics will have code actions (fix + ignoring line/file), only following diagnostics won't:
775	        // - inverted diagnostics (related spans for the diagnostics)
776	        // - diagnostics with span(0,0) and no fixes
777	        // - tsgolint internal diagnostics
778	        // - unused directives diagnostics
779	        let mut code_actions = vec![];
780	        for report in reports {
781	            diagnostics.push(report.diagnostic);
782	
783	            if let Some(code_action) = report.code_action {
784	                code_actions.push(code_action);
785	            }
786	        }
787	
788	        self.code_actions.pin().insert(uri.clone(), Some(code_actions));
789	
790	        Ok(diagnostics)
791	    }
