793	    fn lint_path(
794	        &self,
795	        path: &Path,
796	        uri: &Uri,
797	        content: Option<&str>,
798	    ) -> Result<Vec<DiagnosticReport>, String> {
799	        debug!("lint {}", path.display());
800	
801	        let source_text = if let Some(content) = content {
802	            content
803	        } else {
804	            &read_to_string(path).map_err(|e| format!("Failed to read file: {e}"))?
805	        };
806	
807	        let rope = &Rope::from_str(source_text);
808	
809	        let mut fs = LspFileSystem::default();
810	        fs.add_file(path.to_path_buf(), Arc::from(source_text));
811	
812	        let mut messages: Vec<DiagnosticReport> =
813	            match self.runner.run_source(&[Arc::from(path.as_os_str())], &fs) {
814	                Ok(results) => results
815	                    .into_iter()
816	                    .map(|message| message_to_lsp_diagnostic(message, uri, source_text, rope))
817	                    .collect(),
818	                Err(e) => {
819	                    // clear disable directives on error to prevent stale directives
820	                    self.runner.directives_coordinator().remove(path);
821	                    return Err(e);
822	                }
823	            };
824	
825	        messages.append(&mut generate_inverted_diagnostics(&messages, uri));
826	
827	        // Add unused directives if configured
828	        if let Some(severity) = self.unused_directives_severity
829	            && let Some(directives) = self.runner.directives_coordinator().get(path)
830	        {
831	            messages.extend(create_unused_directives_report(
832	                &directives,
833	                severity,
834	                source_text,
835	                rope,
836	            ));
837	        }
838	
839	        // Clear any stale directives because they are no longer needed.
840	        // This prevents using outdated directive spans if the new linting run fails.
841	        self.runner.directives_coordinator().remove(path);
842	
843	        Ok(messages)
844	    }
